Lemma art_rcy_ev_fp : forall t spb ris qs parr sp1 work G ev z,
  (forall mb ms m b1 n, In (RES mb ms m b1 n) work -> mb mod 4096 = 0 /\ ms mod 4096 = 0 /\ 0 <= mb /\ 0 <= ms) ->
  art_rels_pre G work -> art_rcy_cls G (Z.of_nat (length work)) ->
  In ev (art_rels_events spb G work) -> fst (art_ev_range ev) <= z < snd (art_ev_range ev) ->
  (exists mb ms m b1 n, In (RES mb ms m b1 n) work /\ (mb <= z < mb + ms \/ EatPoison.SB + mb / 8 <= z < EatPoison.SB + mb / 8 + ms / 8))
  \/ ~ art_out (art_rels_fp t spb ris qs parr sp1 G work) z.
Proof.
